// -8 thanks to Xor!

void mainImage( out vec4 o, vec2 u )
{
    vec3 c = iResolution;
    float i, t = .05*iTime;
    u = .4*(u+u-c.xy)/c.y + t;   
    for (o *= i; ++i<14.; o = sqrt(o*o+.7)*.99) 
        u *= -.1*mat2(5, 11, -11, 5), // 1.2*rot(2)
        u += cos(u.yx/.1+ .4*i*o.xz)*.003*i + t/i,
        c = cos(3.*t+vec3(cos(u*1e2),1)/8.+o.x*i/9.+u.x*.4*i+sin(u.y*i)),
        o.rgb += c*pow(c*c, vec3(0,1.5,4))/pow(i,i/43.),
        u += sin(u.yx)*o.z*.03;
    o = 1.-exp(-.018*o*o*o.r);
    //o = pow(o, 1.5-o);
}
